def check_site_with_retry(browser, site, headless, max_retries=SITE_MAX_RETRIES):
    last_results = None
    for attempt in range(max_retries + 1):
        context = browser.new_context()
        page = context.new_page()
        try:
            results = check_site(page, site, headless)
            if not any(r.get("error") for r in results):
                return results
            last_results = results
        except Exception as e:
            print(f"  Failed: {e}")
            last_results = [
                {"site": site["name"], "job_title": "", "status": str(e), "date_applied": "", "error": True}
            ]
        finally:
            context.close()
        if attempt < max_retries:
            print(f"  Retrying {site['name']} (attempt {attempt + 2}/{max_retries + 1})...")
            time.sleep(2)
    return last_results
